-- Bézier curves, see https://wiki.hypr.land/Configuring/Animations/#curves
local bezier_curves = {
    { name = "easeOutQuint",	x0 = 0.23,	y0 = 1,		x1 = 0.32,	y1 = 1		},
    { name = "easeInOutCubic",	x0 = 0.65,	y0 = 0.05,	x1 = 0.36,	y1 = 1		},
    { name = "linear",			x0 = 0,		y0 = 0,		x1 = 1,		y1 = 1		},
